import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';

// Generated by `nestvexa add react`: an independent build for the React
// Inertia root (manifest in dist/react/client/.vite). Other roots are untouched.
// `vite build --ssr client/react/ssr.tsx` writes the server bundle dist/react/ssr/ssr.mjs
// (.mjs: an ES module whatever the project's package type).
export default defineConfig(({ isSsrBuild }) => ({
  base: '/build/react/',
  plugins: [react()],
  server: {
    port: 5173,
    strictPort: true,
    cors: true,
    origin: 'http://localhost:5173',
  },
  build: isSsrBuild
    ? {
        outDir: 'dist/react/ssr',
        emptyOutDir: true,
        rolldownOptions: { output: { entryFileNames: '[name].mjs' } },
      }
    : {
        outDir: 'dist/react/client',
        emptyOutDir: true,
        manifest: true,
        rolldownOptions: { input: 'client/react/app.tsx' },
      },
}));
